UPDATE `ai_playerbot_texts` SET `text_loc4`='您的等级/天赋/级别没有BiS数据，请检查配置，改为运行autogear。' WHERE `name`='bis_no_rows_fallback' AND `text`='No BiS for your tier/spec/level, check cfg, running autogear instead';
