UPDATE `ai_playerbot_texts` SET `text_loc4`='无效的BiS物品等级参数“%param”。请使用正整数。' WHERE `name`='bis_invalid_arg_error' AND `text`='Invalid BiS ilvl argument \'%param\'. Use a positive integer.';
