UPDATE `ai_playerbot_texts` SET `text_loc4`='物品等级%ilvl没有BiS，改用Autogear %ilvl。' WHERE `name`='bis_no_rows_autogear_msg' AND `text`='No BiS at ilvl %ilvl, using Autogear %ilvl instead';
UPDATE `ai_playerbot_texts` SET `text_loc4`='物品等级%requested没有BiS，使用最接近的物品等级%resolved。' WHERE `name`='bis_closest_match_msg' AND `text`='No BiS at ilvl %requested, using closest match at ilvl %resolved';
