UPDATE `ai_playerbot_texts` SET `text_loc4`='你不能在副号机器人上使用autogear。' WHERE `name`='autogear_altbot_refused_error' AND `text`='You cannot use autogear on alt bots.';
UPDATE `ai_playerbot_texts` SET `text_loc4`='我没有可以对齐装备的主人。' WHERE `name`='autogear_no_master_error' AND `text`='I have no master to match gear with.';
UPDATE `ai_playerbot_texts` SET `text_loc4`='你没有装备任何物品，我无法对齐。' WHERE `name`='autogear_master_no_gear_error' AND `text`='You have no gear equipped for me to match.';
UPDATE `ai_playerbot_texts` SET `text_loc4`='配置将我限制为%quality品质，按该品质装备。' WHERE `name`='autogear_quality_capped_msg' AND `text`='Config limits me to %quality quality, gearing to that.';
