UPDATE `ai_playerbot_texts` SET `text_loc4`='未知的autogear选项“%param”。请使用 bis、reset、match、品质（white、green、blue、purple、orange）或正的物品等级数字。' WHERE `name`='autogear_invalid_arg_error' AND `text`='Unknown autogear option \'%param\'. Use bis, reset, match, a quality (white, green, blue, purple, orange) or a positive item level number.';
UPDATE `ai_playerbot_texts` SET `text_loc4`='“%param”看起来像是品质。数字代表物品等级（例如 200）；品质请使用颜色词：white、green、blue、purple、orange。' WHERE `name`='autogear_quality_as_number_error' AND `text`='\'%param\' looks like a quality. Numbers are item levels (e.g. 200); use a colour word for quality: white, green, blue, purple, orange.';
UPDATE `ai_playerbot_texts` SET `text_loc4`='我正在自动装备（%quality，最高物品等级 %ilvl）。' WHERE `name`='autogear_start_msg' AND `text`='I\'m auto gearing (%quality, up to item level %ilvl).';
UPDATE `ai_playerbot_texts` SET `text_loc4`='我正在自动装备（%quality）。' WHERE `name`='autogear_start_any_ilvl_msg' AND `text`='I\'m auto gearing (%quality).';
UPDATE `ai_playerbot_texts` SET `text_loc4`='我正在清空装备并从零重新装备（%quality，最高物品等级 %ilvl）。' WHERE `name`='autogear_reset_start_msg' AND `text`='I\'m erasing my gear and regearing from scratch (%quality, up to item level %ilvl).';
UPDATE `ai_playerbot_texts` SET `text_loc4`='我正在清空装备并从零重新装备（%quality）。' WHERE `name`='autogear_reset_start_any_ilvl_msg' AND `text`='I\'m erasing my gear and regearing from scratch (%quality).';
